  a = [];  // flat binary tree: parent(i) = (i-1)>>1, kids 2i+1, 2i+2

  // earliest end on top; ties broken by lane number
  before(x, y) {
    return x.end - y.end || x.lane - y.lane;
  }

  peek() {
    return this.a[0];        // the lane that frees up first
  }

  push(v) {
    const a = this.a;
    a.push(v);               // drop it at the end...
    let i = a.length - 1;
    while (i > 0) {          // ...then bubble it up
      const p = (i - 1) >> 1;
      if (this.before(a[i], a[p]) >= 0) break;
      this.swap(i, p);       // parent ends later — trade places
      i = p;
    }
  }

  pop() {
    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length) {
      a[0] = last;           // last leaf takes the root...
      let i = 0;
      for (;;) {             // ...then sinks back down
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.before(a[l], a[m]) < 0) m = l;
        if (r < a.length && this.before(a[r], a[m]) < 0) m = r;
        if (m === i) break;  // earlier than both kids — settled
        this.swap(i, m);
        i = m;
      }
    }
    return top;
  }

  swap(i, j) {
    [this.a[i], this.a[j]] = [this.a[j], this.a[i]];
  }
