// lazy deletion: a lie costs one pop, and only if a read reaches it`,Yr=`class StockPrice {
  prices = new Map();   // timestamp → price: THE TRUTH
  latestTime = 0;
  maxHeap = new Heap((a, b) => b.price - a.price);
  minHeap = new Heap((a, b) => a.price - b.price);

  update(ts, price) {
    this.prices.set(ts, price);  // corrections overwrite
    this.latestTime = Math.max(this.latestTime, ts);
    this.maxHeap.push({ price, ts });  // stale entries?
    this.minHeap.push({ price, ts });  // never pruned.
  }

  current() {
    return this.prices.get(this.latestTime);
  }

  maximum() { return this.top(this.maxHeap); }
  minimum() { return this.top(this.minHeap); }

