  // Which meeting is which stops mattering — only the
  // timestamps do. Two tapes, each sorted on its own.
  const starts = intervals.map(iv => iv[0]);
  const ends = intervals.map(iv => iv[1]);
  starts.sort((a, b) => a - b);   // earliest start first
  ends.sort((a, b) => a - b);     // earliest end first

  let rooms = 0;
  let best = 0;
  let startIndex = 0;
  let endIndex = 0;

  // Walk both tapes forward, a finger on each.
  while (startIndex < starts.length) {
    const nextStart = starts[startIndex];
    const nextEnd = ends[endIndex];

    // STRICTLY before: a meeting ending at 5 frees its room
    // for one starting at 5. Use <= and touching meetings
    // would each demand a room of their own.
    if (nextStart < nextEnd) {
      rooms += 1;   // a meeting begins — claim a room
      startIndex += 1;
      best = Math.max(best, rooms);
    } else {
      rooms -= 1;   // a meeting ended — hand a room back
      endIndex += 1;
    }
  }
  return best;
