  store = new Map();   // key → [ts, value], ts ascending

  set(key, value, timestamp) {
    const versions = this.store.get(key) ?? [];
    versions.push([timestamp, value]);   // stamps arrive sorted
    this.store.set(key, versions);
  }

  get(key, timestamp) {
    const versions = this.store.get(key);
    if (versions === undefined) return '';   // never set

    let lo = 0;
    let hi = versions.length - 1;
    let best = '';

    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      const [stamp, value] = versions[mid];
      if (stamp <= timestamp) {
        best = value;    // old enough — a candidate
        lo = mid + 1;    // look right for something newer
      } else {
        hi = mid - 1;    // too new — so is everything right of it
      }
    }

    return best;   // newest stamp at or before the question
  }
