  // 1. COUNT — one pass, read-modify-write.
  const counts = new Map();
  for (const item of items) {
    const seenSoFar = counts.get(item) ?? 0;
    counts.set(item, seenSoFar + 1);
  }

  // 2. THE FLIP — seen c times goes into bucket c.
  //    Nothing can appear more often than the list is
  //    long, so buckets 0..n cover every possibility
  //    and no bucket can be missing. NO SORTING here.
  const buckets = Array.from({length: items.length + 1}, () => []);
  for (const [item, count] of counts) {
    buckets[count].push(item);
  }

  // 3. WALK DOWN from the highest count. The counts are
  //    never compared — they sorted themselves by being
  //    used as addresses.
  const top = [];
  for (let count = buckets.length - 1; count >= 0; count--) {
    const haveEnough = top.length >= k;
    if (haveEnough) break;
    for (const item of buckets[count]) top.push(item);
  }

  return top.slice(0, k);   // the last bucket may overshoot
