  let lastRunAt = -Infinity;  // when fn last actually ran
  let pendingTimer;           // the ONE trailing run
  let queuedArgs;             // newest args we had to skip

  // Every run — leading or trailing — shuts the window.
  const run = (args) => {
    lastRunAt = Date.now();
    fn(...args);
  };

  return (...args) => {
    const sinceLastRun = Date.now() - lastRunAt;
    const msLeftInInterval = interval - sinceLastRun;

    if (msLeftInInterval <= 0) {
      // Window open: straight through — the leading edge.
      clearTimeout(pendingTimer);
      queuedArgs = undefined;
      run(args);
      return;
    }

    // Window shut. Keep the newest args, and make sure
    // exactly ONE trailing run is scheduled — not one per
    // skipped call, which is the bug people ship.
    queuedArgs = args;
    if (pendingTimer === undefined) {
      pendingTimer = setTimeout(() => {
        pendingTimer = undefined;
        run(queuedArgs);   // the trailing edge
      }, msLeftInInterval);
    }
  };
