  // Two fingers, as far apart as they can possibly be.
  let left = 0;
  let right = heights.length - 1;
  let best = 0;

  while (left < right) {
    // Water spills over the SHORTER wall, so the shorter
    // wall sets the depth and the gap sets the width.
    const width = right - left;
    const depth = Math.min(heights[left], heights[right]);
    best = Math.max(best, width * depth);

    // The proof, in one move: every pair still to come is
    // NARROWER, and any pair still using the shorter wall
    // is capped no higher — so none of them can beat the
    // area we just measured. Retire the shorter wall.
    if (heights[left] < heights[right]) {
      left++;
    } else {
      right--;
    }
  }
  return best;
