  let left = 0;
  let right = heights.length - 1;
  let maxLeft = 0;   // tallest bar left has walked past
  let maxRight = 0;  // tallest bar right has walked past
  let water = 0;

  while (left < right) {
    // Settle the SHORTER side. Its own best wall is the
    // spill point: the other side already has a wall at
    // least this tall and can only find taller ones, so
    // nothing in the unseen middle can change this column.
    if (heights[left] < heights[right]) {
      maxLeft = Math.max(maxLeft, heights[left]);
      water += maxLeft - heights[left];
      left++;
    } else {
      maxRight = Math.max(maxRight, heights[right]);
      water += maxRight - heights[right];
      right--;
    }
  }
  return water;
