// is drawn at p·k + x (d3 also keeps y).
function Transform(k, x) {
  this.k = k;
  this.x = x;
}
Transform.prototype.applyX = function (x) {
  return x * this.k + this.x;
};
Transform.prototype.invertX = function (x) {
  return (x - this.x) / this.k;
};

// d3-zoom/src/zoom.js
const scaleExtent = [1, 8];
function scale(transform, k) {
  k = Math.max(scaleExtent[0], Math.min(scaleExtent[1], k));
  return k === transform.k ? transform : new Transform(k, transform.x);
}
// Pick x so that unzoomed point p1 is drawn at screen point p0.
function translate(transform, p0, p1) {
  const x = p0 - p1 * transform.k;
  return x === transform.x ? transform : new Transform(transform.k, x);
}

