function translate(tx, ty) {
  return [[1, 0, tx], [0, 1, ty], [0, 0, 1]];
}

function scale(k) {
  return [[k, 0, 0], [0, k, 0], [0, 0, 1]];
}

// Zoom by k about the point p (lesson 1): p stays where it is.
function zoomAt(p, k) {
  const toOrigin = translate(-p[0], -p[1]);
  const back = translate(p[0], p[1]);
  return multiply(back, multiply(scale(k), toOrigin));
}

