const timers = [];
let now = 0;

// MPJ's fake store (funfuniterators, fake-store-async.js):
// customers and their foods, each answered 50ms later.
const TABLES = {
  customer: {1: {name: 'John'}, 2: {name: 'Mattias'}, 3: {name: 'Kim'}},
  food: {1: ['cake', 'waffle'], 2: ['coffee'], 3: ['apple', 'carrot']},
};

